class ComplexCalculator:
    def __init__(self):
        pass

    @staticmethod
    def _compute_addition_result(c1, c2):
        real = c1.real + c2.real
        imaginary = c1.imag + c2.imag
        return complex(real, imaginary)

    @staticmethod
    def _compute_subtraction_result(c1, c2):
        real = c1.real - c2.real
        imaginary = c1.imag - c2.imag
        return complex(real, imaginary)

    @staticmethod
    def _compute_multiplication_result(c1, c2):
        real = c1.real * c2.real - c1.imag * c2.imag
        imaginary = c1.real * c2.imag + c1.imag * c2.real
        return complex(real, imaginary)

    @staticmethod
    def _compute_division_result(c1, c2):
        denominator = c2.real**2 + c2.imag**2
        real = (c1.real * c2.real + c1.imag * c2.imag) / denominator
        imaginary = (c1.imag * c2.real - c1.real * c2.imag) / denominator
        return complex(real, imaginary)

    @staticmethod
    def add(c1, c2):
        return ComplexCalculator._compute_addition_result(c1, c2)

    @staticmethod
    def subtract(c1, c2):
        return ComplexCalculator._compute_subtraction_result(c1, c2)

    @staticmethod
    def multiply(c1, c2):
        return ComplexCalculator._compute_multiplication_result(c1, c2)

    @staticmethod
    def divide(c1, c2):
        return ComplexCalculator._compute_division_result(c1, c2)
